SET NAMES utf8mb4;
USE `navaraby_wp569`;
START TRANSACTION;
SET @existing_post=(SELECT ID FROM `ha_posts` WHERE `post_name`='آجین-همدان-looleh-nakhi-tashoo' AND `post_type`='hamadan' LIMIT 1);
SET @created_post=IF(@existing_post IS NULL,1,0);
SET @post_id=COALESCE(@existing_post,LAST_INSERT_ID());
SET @media_1=(SELECT ID FROM `ha_posts` WHERE post_parent=@post_id AND post_type='attachment' AND post_name='لوله-نخی-تاشو-آجین-همدان-looleh-nakhi-tashoo-تصویر-شاخص' LIMIT 1);
SET @media_1=COALESCE(@media_1,LAST_INSERT_ID());
SET @media_2=(SELECT ID FROM `ha_posts` WHERE post_parent=@post_id AND post_type='attachment' AND post_name='لوله-نخی-تاشو-آجین-همدان-looleh-nakhi-tashoo-راهنمای-انتخاب' LIMIT 1);
SET @media_2=COALESCE(@media_2,LAST_INSERT_ID());
SET @media_3=(SELECT ID FROM `ha_posts` WHERE post_parent=@post_id AND post_type='attachment' AND post_name='لوله-نخی-تاشو-آجین-همدان-looleh-nakhi-tashoo-جزئیات-فنی' LIMIT 1);
SET @media_3=COALESCE(@media_3,LAST_INSERT_ID());
COMMIT;
